<main class="py-5"><div class="container"><div class="row justify-content-center"><div class="col-lg-7"><section class="card border-0 shadow-sm"><div class="card-body p-4 p-md-5 text-center"><span class="badge text-bg-success">Commande enregistrée</span><h1 class="h2 text-primary mt-3">Merci pour votre commande</h1><p>Votre demande #<?= $order->getId() ?> a été créée pour le <?= $escape($order->getDeliveryDate()) ?>.</p><dl class="row text-start mt-4"><dt class="col-sm-5">Menu</dt><dd class="col-sm-7"><?= $escape($menu?->getTitle() ?? 'Menu') ?></dd><?php if ($order->getCustomization()): ?><dt class="col-sm-5">Options choisies</dt><dd class="col-sm-7"><?= $escape($order->getCustomization()) ?></dd><?php endif; ?><dt class="col-sm-5">Nombre de personnes</dt><dd class="col-sm-7"><?= $order->getNumberOfPeople() ?></dd><dt class="col-sm-5">Prix menu après remise</dt><dd class="col-sm-7"><?= number_format($order->getMenuPrice(), 2, ',', ' ') ?> €</dd><dt class="col-sm-5">Remise</dt><dd class="col-sm-7"><?= number_format($order->getDiscountRate(), 0) ?> %</dd><dt class="col-sm-5">Livraison</dt><dd class="col-sm-7"><?= number_format($order->getDeliveryCost(), 2, ',', ' ') ?> €</dd><dt class="col-sm-5">Total</dt><dd class="col-sm-7"><?= number_format($order->getTotalPrice(), 2, ',', ' ') ?> €</dd></dl><a class="btn btn-primary" href="/orders">Voir mes commandes</a></div></section></div></div></div></main>
